PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?country
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/The_Brand_New_Testament> 
    <http://dbpedia.org/resource/The_Boss_of_Rustler's_Roost>
  }
  OPTIONAL { ?film dbo:country ?country }
  OPTIONAL { ?film dbp:country ?country }
}
LIMIT 100

